float gz = 50;
float dt = 0.02;
float enk = 20;
const float ALFA = 0.98;

void setup() {
  Serial.begin(9600);
  yon = ALFA * (yon + gz * dt) + (1 - ALFA) * enk;
  Serial.println(yon, 2);
}

void loop() {}
```

